from pathlib import Path
import os

def load_file(name):
    path = (Path("uploads") / name).resolve()
    if not path.is_relative_to(Path("uploads").resolve()):
        raise ValueError("invalid path")

    os.chmod(path, 0o777)
    return path.read_bytes()
